-- ElectroHomeSY - mevcut ürünlerin ilk aktarımı (products.json + Google Sheets stok miktarları)
-- schema.sql'den SONRA bir kez çalıştırın. Aynı id'li ürün varsa üzerine yazmaz.
on conflict (id) do nothing;

-- Yeni eklenecek ürünlerin numarası mevcutların devamından başlasın
select setval(pg_get_serial_sequence('public.products', 'id'), (select coalesce(max(id), 1) from public.products));
